//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::string::utf8_set`; the
//! native twin is `benches/native/Bench/StringUtf8Set.lean`.
//! the string is updated in place where it can be on both sides (Lean's is unique after its first
//! copy of the input): Lean's C in place for an ASCII character over an ASCII one, else a copy
//! into a new string; the Rust twin's glue in place for a character of the same size
//! (Utf8Set::write_in_place), else one new block; any position up to two past the end, characters
//! of 1 to 4 bytes

#![allow(unused_parens, unused_imports, unused_variables, unused_mut)]
#![allow(
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]
#![allow(clippy::identity_op, clippy::let_and_return)]

use lean_runtime::semantics::string;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &PosInput, n: u64) -> u64 {
    let (s, ps) = (inp.s.as_bytes(), &inp.ps[..]);
    let mut st = s.to_vec();
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        if let Some(ch) = string::utf8_set(
            &st,
            nat_unbox(get_word(ps, x >> 52)),
            (match (x >> 8) & 3 {
                0 => 'x',
                1 => 'é',
                2 => '€',
                _ => '😀',
            } as u32),
        ) {
            if ch.same_size() {
                ch.write_in_place(&mut st);
            } else {
                let mut v = Vec::with_capacity(ch.result_size(st.len()) + 1);
                v.extend_from_slice(&st[..ch.start]);
                v.extend_from_slice(ch.new_bytes());
                v.extend_from_slice(&st[ch.end..]);
                st = v;
            }
        }
        acc = mix(acc, {
            let k = (x >> 40) & 511;
            st.len() as u64
                + if k < st.len() as u64 {
                    u64::from(string::get_byte_fast(&st, k))
                } else {
                    0
                }
        });
    }
    acc
}

fn main() {
    run(|| pos_input(mixed(), Positions::Any), kernel)
}
